// =====================================================================================================================
//  OctaviOS app reference: annotated API + demos. Engine: octavios dev >= 609d5ae (2026-10-21, fw-0.100.6-dev).
//  ../API.md is the compact index of every call, limit and rule (read it first); this file shows them in use.
//  Tap a face to step through the demos (DEMO_0 .. DEMO_20); in demos 17, 18 and 20 a single tap acts on the demo and
//  a double tap moves on.
// =====================================================================================================================

// --- INSTRUCTIONS FOR AI AGENT -----------------------
// * This file is a reference for OctaviOS API usage. A new game starts from src/app_structure_example.h.
// * DO NOT copy code 1:1.
// * DO NOT copy internal comments from demos/apis.
// * Use this as a guide to implement specific logic.
// * ALWAYS use explicit type casts - never rely on implicit conversions between numeric types, pointers, or enums.
//   Every narrowing, widening, or cross-type assignment must have a visible cast.
// * Use only fixed-width types from <stdint.h> (int8_t, int16_t, int32_t, uint8_t, uint16_t, uint32_t, size_t, etc.).
//   Never use plain int, short, long - except in the callback signatures, which the engine fixes.
// * ALWAYS copy the project header structure.
// * ALWAYS define the six mandatory callbacks: on_init, on_tick, on_pretwisted, on_twisted, on_tap, on_shake.
//   on_proc_draw, on_save, on_save_synced and on_dock exist ONLY together with their APP_HAS_* define in
//   src/app_metadata.h: a define without the function fails to build, a function without the define is never called.
// * Write modular, readable code: extract game state into structs, split logic into small focused functions, use named
//   constants instead of magic numbers.
// * The ARM build is -Wall -Werror (any warning fails the build): no double (float literals are single precision;
//   never pass a float to OCT_text/snprintf, print it with OCT_F_INT/OCT_F_FRAC), no strlen/strcmp/strcpy, and
//   snprintf knows only %d %u %ld %lu %zu %Nd %0Nd %s %c %% (cast to int32_t/uint32_t and use %d/%u).
// -----------------------------------------------------

// --- CALLBACKS (octavios dev) ------------------------------------------------------------------------------------------
// Mandatory, always exported (apps/src/app_module.cpp references all six; the binder refuses a module without
// on_init/on_tick):
//   on_init()                 once per launch, inside a tick shared by all 8 modules. OCT_restart FIRST (see on_init).
//   on_tick()                 20 times a second while the game is not held (dock pause, battery save after 60 s idle,
//                             save sync, incoming install, critical battery). The app is NOT told about holds: ticks,
//                             frame sequences, tweens and input simply stop.
//   on_pretwisted(side)       a layer started turning on SIDE 0..5 (a plane, not a twist id). It arrives as a command
//                             on all 8 modules, but it may never be followed by on_twisted (the twist was abandoned).
//   on_twisted(twid, ms)      twist done, the engine already moved the twistable sprites. twid 0..11 = full twist,
//                             12..23 = half twist (turned and back, moved nothing). A 180-degree twist arrives as TWO
//                             calls with the same twid. `ms` is a TIMESTAMP (leader clock), not a duration.
//   on_tap(tapid, count)      tapid = plane 0..5; count = place in a quick series on that side (1, 2, ... max 7),
//                             delivered tap by tap. The exact screen: appTapQuad(tapid) (OCT_tap_source).
//   on_shake(shakeid)         must exist, never called: a shake always exits a plain game (on_save runs first).
// Optional, exported only under their define in app_metadata.h:
//   on_proc_draw(...)         APP_HAS_PROC_DRAW       draws PROCEDURAL_CUSTOM sprites (render path, per module)
//   on_save()                 APP_HAS_ON_SAVE         store the record on exit, dock reset and sleep: no anim, no sound
//   on_save_synced(result)    APP_HAS_ON_SAVE_SYNCED  verdict of OCT_save_sync, same tick on all 8 modules
//   on_dock(docked)           APP_HAS_ON_DOCK         APP_CATEGORY_SYSTEM apps holding OCT_shake_exit_block(true) only
// A game is never resumed after sleep or a re-assembly: the cube relaunches HOME. Restore progress from the save area.

// --- LOCKSTEP: 8 copies of this app ------------------------------------------------------------------------------------
// Each module runs its own copy with its own state and draws its own 3 screens; nothing is ever reconciled. The copies
// stay identical only because they get the same commands (taps, twists, launches, save verdicts) on the same tick and
// call on_tick the same number of times in between. Rules:
//  * Every global is TL (thread_local in the simulator, where the 8 modules are 8 threads; empty on the cube).
//  * Game state may draw OCT_random() in on_init, on_tick and the input callbacks (the engine re-anchors it per tick and
//    per command), NEVER in on_proc_draw. Draws after OCT_restart inside on_init repeat on every launch (the seed is
//    reset to 1): roll random levels in the first on_tick instead.
//  * Cosmetic randomness that may differ per face (particle jitter, idle wobble): OCT_random_local(). It may set only
//    values that game logic never reads back (position jitter, colour, frame) - never whether a sprite exists, never
//    anything stored in game state (demo 19).
//  * Per-module values (display only, never game logic): OCT_random_local, OCT_acc_visual_*, OCT_disconnected_axis,
//    OCT_screen_quad, OCT_cube_pose_visual (outside the tick), OCT_gesture_probe, OCT_BAT_level_local,
//    OCT_calendar_time, OCT_get_progress, the RETURN VALUES of SND_play / SND_play_quad, OCT_save_read contents (each
//    module reads its own card: sync first), everything inside on_proc_draw.
//  * Same on all 8 (safe for logic): the tick count, OCT_TM_gravity_*/acc_*/mixed_acc_*/tap_*, OCT_TM_top_side /
//    bottom_side, OCT_TM_face_up, OCT_tap_source, OCT_cube_pose / OCT_module_pose, the on_save_synced verdict.
//  * Key logic to commands or to your own tick counter; keep each callback's number of OCT_random draws independent of
//    per-tick history.

// --- COORDINATES ------------------------------------------------------------------------------------------------------
// Plane space: X right, Y UP, origin = face centre, |X|,|Y| < LIM = 240 + 2 * GAP (276). Quad q 0..3 (CCW from +X+Y,
// signs XSIGN/YSIGN) covers |x|,|y| in [GAP, 240 + GAP]; the cross 0..GAP and the outer rim are bezel (invisible).
// Scene quad id = plane * 4 + q (OCT_TM_quad), 0..23. OCT_add / OCT_add_label with plane 0..5 push x,y outward by GAP
// for you: pass (+-120, +-120) for quad centres. Everything else is RAW: OCT_TM_set/move/walk, tweens and direct Tm
// writes put a quad centre at (+-(120 + GAP), +-(120 + GAP)); the screen-to-screen step on one face is 240 + 2 * GAP.
// Screen-FILLING art goes at +-QUAD_FILL (119.5), not +-120 (a thin background cross otherwise; see QUAD_FILL).
// OCT_add with plane OCT_PLANE_WITH_BORDER + p (10..15) = raw coordinates, no push. Angles 0/90/180/270 only, CCW
// positive, 0 = +X. Screen space is swapped: screen x = Tm.Y, screen y = Tm.X, screen angle = 90 - Tm.A.
// Opposite faces never see each other and opposite-plane conversions terminate: route through an adjacent plane.

// --- ART AS THE APP SEES IT -------------------------------------------------------------------------------------------
// Every bitmap is a BMP_* id (its order in index.bin); OCT_add / OCT_sequence draw every format the same way. The format
// is chosen at pack time, not in code, and decides only what the renderer can do with it:
//   palette, half-res (default)   art at half size, drawn x2; <= 256 colours, index 0 transparent; Transp + all tints
//   palette <FULLSIZE>            drawn 1:1 and ALWAYS above every half-res sprite (separate full-res pass)
//   RAW565 plain / RLE            "full colour" in the pipeline manifest: opaque rectangle, no alpha, Transp ignored
//   RAW565 SOFTKEY                full colour with a colour-keyed cut-out (octpacker <SOFTKEY><KEY=RRGGBB>), no Transp
//   ARGB6666 / ARGB6666_RLE       true colour + 6-bit alpha per texel, Transp honoured (octpacker <ARGB>)
//   MONO1                         1-bit, two inks, FULLSIZE; made by the engine (QR codes), no packer token for apps
// Tinting works on all of them (palette art costs per palette entry, raw art per pixel). OCT_BMP_info gives W/H in
// screen pixels, pivot and bounds, not the format. The pipeline's packer (scripts/pack_beta.py) writes palette and
// RAW565 only; SOFTKEY and ARGB6666 need octavios octpacker.

// --- FIRMWARE COMPATIBILITY -------------------------------------------------------------------------------------------
// Imports newer than the cube's firmware read NULL. Most module macros guard that (they return 0 / false /
// OCT_SAVE_UNSUPPORTED or do nothing). FOUR DO NOT and crash (jump to 0) on older firmware: OCT_label_static,
// OCT_tint and SND_play_quad (need fw-0.98.19), OCT_bootloader_build_id (fw-0.98.17); OCT_tint_mode with
// OCT_BLEND_MUL falls back to OCT_tint, so it needs fw-0.98.19 as well. Target cubes on current firmware, or guard:
//   #ifdef OCT_APP_MODULE  if (OCT_APP_IMPORTS.label_static != NULL) { ... }  #endif


#define OCT_PLANES_MAX 6 // planes on the cube (engine: SIDES_COUNT)
#define OCT_QUADS_AT_PLANE 4 // screens per plane (engine: SECTORS_COUNT)
#define OCT_QUADS_TOTAL (OCT_PLANES_MAX * OCT_QUADS_AT_PLANE) // 24 screens = scene quads 0..23

// The app's own sprite pool (gObjects[]). It lives in the 256 KB module image together with the code: SPRITES_CAP *
// sizeof(appObject_t) must fit (80 B per sprite plus your fields; here 400 * 104 B = 41.6 KB). OCT_restart accepts
// 2..OCT_SPRITES_CAP (5120), ~1500-2000 is the practical ceiling. Usable sprites = SPRITES_CAP - 2 (slot 0 is the
// free-list head, the last slot the terminator). At most OCT_SPRITES_QUAD_CAP (512) sprites are drawn per screen.
#define SPRITES_CAP 400
#define GAP 18 // width of the physical border between WowCube's displays in pixels (OCT_viewports_layout inner border)
// Centre for SCREEN-FILLING art (backgrounds, panorama pieces, edge-to-edge tiles): OCT_add(..., XSIGN[q] * QUAD_FILL,
// YSIGN[q] * QUAD_FILL, ...), raw coordinates +-(QUAD_FILL + GAP). Not 120: a full-screen sprite's pivot is 119.5 (its
// middle pixel centre) and the renderer rounds the corner, so at +-120 a 2-px line of the background shows on two inner
// edges of every face (1 px for <FULLSIZE> art).
#define QUAD_FILL 119.5f
// Never define SIM_SINGLE_THREAD: it makes only module 0 run the app in the simulator (hiding lockstep bugs), while
// on_save, on_save_synced and on_dock still run on all 8 modules against never-initialised state. Dev's template omits
// it and scripts/new_app.* strip it.

// Print a float through OCT_text/OCT_trace without %f (double is poisoned on ARM).
// Split into integer and 3-digit fractional parts, format as "%d.%03d":
//   OCT_text(-1, "x=%d.%03d\n", OCT_F_INT(x), OCT_F_FRAC(x));
// Note: for values in (-1, 0) the sign lives in the fractional part only, so e.g. -0.5 prints as "0.500".
#define OCT_F_INT(x) ((int32_t)(x))
#define OCT_F_FRAC(x) ((int32_t)(((x) < 0.0f ? -(x) : (x)) * 1000.0f) % 1000)

// --- TEST HOOKS -------------------------------------------------------------------------------------------------------
// Every game carries exactly these three switches: <GAME>_DEBUG_AUTOPLAY, <GAME>_MUTE, <GAME>_DEBUG_ROOM_PLANE, with the
// game's short upper-case prefix (TPL_ here, e.g. TD_ for till_dawn; the orchestrator records them as test_hooks).
// Release and device builds keep the defaults below. Agent test builds flip them from outside (the hidden simulator's
// build.ps1 -Define, or -D on the compiler), hence the #ifndef guards: screenshots of all 24 screens, gameplay video,
// balance runs. The hidden simulator never opens an audio device; MUTE is the guarantee for every other run.
#ifndef TPL_DEBUG_AUTOPLAY
#define TPL_DEBUG_AUTOPLAY 0      // 1 = the game plays itself (here: steps through the demos on its own)
#endif
#ifndef TPL_MUTE
#define TPL_MUTE 0                // 1 = no sound at all: playSound()/playSoundAt() compile to nothing
#endif
#ifndef TPL_DEBUG_ROOM_PLANE
#define TPL_DEBUG_ROOM_PLANE (-1) // 0..5 = playfield pinned to this face (no tilt needed); -1 = normal
#endif


