// utils

// Util: copy this code if needed
appObject_t* spriteAt(int32_t id) {
    // API info + util
    // OCT_add / OCT_add_label return the new sprite's index in gObjects, or 0 when the pool is full (or a bitmap id is
    // negative). Slot 0 is the pool's free-list head: never touch gObjects[0]. Convert to a pointer right away and
    // treat NULL as "no sprite".
    return (id > 0 && id < (int32_t)SPRITES_CAP) ? &gObjects[id] : NULL;
}

// Util: copy this code if needed
bool isAlive(const appObject_t* obj) {
    // API info + util
    // True while obj points at a live slot of the pool (Idx equals its own index; freed slots hold a free-list link).
    // It does NOT prove it is still the SAME sprite: OCT_del frees the slot and the next OCT_add reuses it (LIFO), and
    // Autokill sprites vanish on their own. Null your pointer whenever you delete the sprite, and never keep pointers
    // to Autokill sprites.
    return obj != NULL && (int32_t)obj->Idx == (int32_t)(obj - gObjects);
}

// Util: copy this code if needed
appObject_t* getQuadContent(size_t quad) {
    // API info + util

    // A quad represents a physical display on a plane. Its size is 240x240.
    // Quads [0; 3] start from the top-right center (120 + GAP; 120 + GAP) and rotate CCW.
    // quadId = quad [0; 3] + plane_id * OCT_QUADS_AT_PLANE

    // gObjects[0] is never a sprite: slot 0 is the pool's free-list head. Start from 1 and check Idx == i (alive).
    for (size_t i = 1; i < SPRITES_CAP; i++) {
        appObject_t* obj = &gObjects[i];

        // Check for a valid object (Idx always equals the object ID).
        if ((size_t)obj->Idx != i) continue; // Invalid object

        // Short: OCT_TM_quad returns the quad ID where the given transform (octTm_t) is located.
        // Declaration: int OCT_TM_quad(const octTm_t* tm);
        // Comment: Every sprite (octSprite_t) has a transform property (Tm) of type octTm_t. Result = Plane * 4 + local quad (by the signs of X and Y).
        if((size_t)OCT_TM_quad(&obj->Tm) == quad) return obj;

        // Second method: do not copy this!
        {
            // Short: Manual calculation of quad content based on coordinates.
            // Comment: XSIGN and YSIGN determine the sign of X and Y coordinates for each local quad [0; 3].
            // Warn: do not redeclare XSIGN and YSIGN! They are already declared in `oct_shared.h`.

            // XSIGN: {+1, -1, -1, +1}
            // YSIGN: {+1, +1, -1, -1}

            int16_t plane = (int16_t)(quad / OCT_QUADS_AT_PLANE);
            int16_t lQuad = (int16_t)(quad % OCT_QUADS_AT_PLANE);

            if ((int16_t)obj->Tm.Plane == plane && obj->Tm.X * (float)XSIGN[lQuad] > 0 && obj->Tm.Y * (float)YSIGN[lQuad] > 0) return obj;
        }

    }
    return NULL;
}

// Util: copy this code if need to modify label properties
void showLabel(appObject_t* label, bool show) {
    // API + util
    // Short: Toggles visibility of a label and all its child glyphs (letters).
    // Comment: A label filled by OCT_label_set / OCT_label_static has child sprites (one per glyph) linked via Parent.
    // Comment: Hidden is per sprite: hiding the label alone does not hide its glyphs - each child must also be toggled. (OCT_label_embed text has no glyph children.)
    if (label == NULL) return;
    label->Hidden = !show;

    for (size_t i = 1; i < SPRITES_CAP; i++) {
        appObject_t* obj = &gObjects[i];
        if ((size_t)obj->Idx != i) continue;

        // check if object is child of label
        if (obj->Parent == label->Idx) {
            obj->Hidden = !show;
        }
    }
}

// Util: copy this code if needed
// The face that is up, with the engine's own top-change rule (oct_tm.h OCT_TM_face_up_update: the challenger must lead
// by OCT_TM_TOP_HYSTERESIS 0.29 in gravity_n, ~12 degrees past 45). OCT_TM_top_side() has no hysteresis: between ~45
// and ~57 degrees it already names the new face while OCT_TM_face_up still holds the old top's latch. This one switches
// together with that latch (checked in the simulator: 55 degrees keeps it, 60 switches; back at 40 it holds, at 30 it
// returns). Keep *held in your vars, -1 at start; gravity_n is the same on all 8 modules, so it is lockstep-safe.
#define TOP_HYSTERESIS 0.29f
static inline int32_t topWithHysteresis(int32_t* held) {
    int32_t c = (int32_t)OCT_TM_top_side();
    if (*held < 0 || *held >= SIDES_COUNT ||
        (c != *held && OCT_TM_gravity_n(c) <= OCT_TM_gravity_n(*held) - TOP_HYSTERESIS)) *held = c;
    return *held;
}

// Util: copy this code if needed
int32_t playfieldPlane(void) {
    // API info + util
    // The face the playfield lives on: the face that is up (with the engine's hysteresis, held in vars.heldTop, -1 at
    // on_init), unless the TPL_DEBUG_ROOM_PLANE test hook pins it. Call it once per tick and keep the result.
#if TPL_DEBUG_ROOM_PLANE >= 0
    return (int32_t)TPL_DEBUG_ROOM_PLANE;
#else
    // Short: OCT_TM_top_side / OCT_TM_bottom_side return the plane facing up / down (from the leader's gravity, the same on all 8 modules, no hysteresis).
    // Declaration: int OCT_TM_top_side(); int OCT_TM_bottom_side();
    // Comment: raw top_side switches ~12 degrees before OCT_TM_face_up's latch does; topWithHysteresis switches with it.
    return topWithHysteresis(&vars.heldTop);
#endif
}


// sound

// Util: copy this code if needed
void resolveSounds(void) {
    // API info + util
    // Short: SND_getAssetId returns the asset id of a packed sound by its file name (".mp3"/".wav" is stripped), or -1.
    // Declaration: int SND_getAssetId(const char* name);
    // Comment: a linear name search over the pack: resolve once in on_init and keep the ids (or use the SND_* ids of the generated _ids.h when the packer writes them). Asset names are <= 23 characters.
    // Comment: sound files are MP3, 22 050 Hz, mono, 32 kbps CBR, no Xing/ID3 tags (the pack step encodes them); any length (streamed).
    vars.snd.music = (int32_t)SND_getAssetId("digit_merge0.mp3");
    vars.snd.sfxA = (int32_t)SND_getAssetId("digit_merge1.mp3");
    vars.snd.sfxB = (int32_t)SND_getAssetId("digit_merge2.mp3");
}

// Util: copy this code if needed
void playSound(int32_t id, int32_t volume) {
    // API info + util
    // Every sound of the game goes through this function (and playSoundAt): TPL_MUTE compiles all of them out, and the
    // return value is dropped on purpose (it is per module, see below).
    // Short: SND_play adds a sound to THIS module's mixer; returns 1 accepted, 0 refused.
    // Declaration: int SND_play(int id, int volume);
    // Comment: mixer on (the default): sounds ADD UP, up to 6 voices per module (shared with system chimes); with all 6 busy the new sound is refused and nothing playing is cut. Keep source peaks moderate: the sum saturates.
    // Comment: volume 0..100 is a linear per-voice gain and is honoured (the user's master volume sits on top). Any length.
    // Comment: game logic runs on all 8 modules, so a plain SND_play sounds on all 8 speakers (right for music and global events). A sound that belongs to a place: playSoundAt / SND_play_quad.
    // Comment: the return value is PER MODULE (voice pool, simulator: modules 1..7 always get 0): never branch game state on it.
    // Comment: no stop, loop, pause or is-playing API: a voice ends at its end of file (see updateMusic, demo 17).
#if TPL_MUTE
    (void)id; (void)volume;
#else
    if (id <= 0) return;
    SND_play(id, volume);
#endif
}

// Util: copy this code if needed
void playSoundAt(int32_t id, int32_t volume, int32_t quad) {
    // API info + util
    // Short: SND_play_quad plays a sound only on the module that currently shows scene quad 0..23; every other module returns 0.
    // Declaration: int SND_play_quad(int id, int volume, int quad);
    // Comment: the quad is a SCENE quad (OCT_TM_quad numbering), so the sound follows its place across twists: pass OCT_TM_quad(&obj->Tm) for a sound coming from a sprite, or appTapQuad(tapid) for the tapped screen. A quad nobody shows -> 0 everywhere.
    // Comment: the simulator does not filter by placement (the leader plays it, whichever module owns the quad).
    // Warn: no NULL guard in the module macro: needs cube firmware >= fw-0.98.19, older firmware crashes.
#if TPL_MUTE
    (void)id; (void)volume; (void)quad;
#else
    if (id <= 0 || quad < 0 || quad >= OCT_QUADS_TOTAL) return;
    SND_play_quad(id, volume, quad);
#endif
}

// Util: copy this code if the game has music
void updateMusic(void) {
    // API info + util
    // A music bed: the engine cannot loop or stop a sound, so on_tick re-issues the track every MUSIC_LOOP_TICKS.
    // Deterministic on all 8 modules because it counts the game's own ticks; never retry on SND_play's return value.
    // Expect a small gap or overlap at the seam (decoder prefill + mp3 padding); an overlap briefly takes a second voice.
    // Budget: the bed takes 1-2 of the 6 voices per module, leaving 4-5 for effects. A bed that must stop on cue: split
    // the track into short segments (1-4 s) and stop scheduling the next one (latency <= one segment).
    if (vars.tick < vars.demo17.musicNextTick) return;
    playSound(vars.snd.music, MUSIC_VOLUME);
    vars.demo17.musicNextTick = vars.tick + MUSIC_LOOP_TICKS;
}


// save (needs `#include "app_save.h"` in app_metadata.h; without a save area every call answers OCT_SAVE_NO_AREA)

// Util: copy this code if the game keeps a save
void saveBegin(void) {
    // API info + util
    // Called from on_init. Each module keeps its OWN copy of the save area on its own card. When the saved data
    // drives game logic (unlocked level, difficulty), first make the 8 copies identical with OCT_save_sync, then read.
#if defined(APP_SAVE_SIZE) && defined(APP_HAS_ON_SAVE_SYNCED)
    // Short: OCT_save_sync makes the LEADER's bytes of a range the bytes on all 8 modules; returns OCT_SAVE_OK when the sync started.
    // Declaration: int OCT_save_sync(uint32_t offset, uint32_t size);
    // Comment: only from inside the tick (on_init, on_tick, the input callbacks, on_save_synced); range <= 64 KB. The engine HOLDS the game on all 8 modules (no on_tick, no input; a "Syncing" pill after 0.5 s) until on_save_synced(result) arrives; deadline 200 ticks = 10 s, then OCT_SAVE_NOT_SYNCED. Use it at on_init or level boundaries, never every tick.
    // Until a successful verdict the 8 cards may hold different records: every module starts from the SAME defaults
    // and nothing is written (a write here would put a never-loaded record over a good save).
    saveDefaults();
    vars.save.valid = false;
    vars.save.lastResult = (int32_t)OCT_save_sync(0U, (uint32_t)sizeof(saveRecord_t));
    // No sync started (no save area, old firmware, range refused): keep the identical defaults and leave writes off
    // for this session. Never fall back to reading the own card - the records can differ between modules and they
    // drive game logic, so the 8 copies of the game would diverge.
#elif defined(APP_SAVE_SIZE)
    saveLoad(); // display-only data: each module may read its own card
#else
    vars.save.valid = false;
    vars.save.lastResult = OCT_SAVE_NO_AREA;
#endif
}

// Util: copy this code if the game keeps a save
void saveLoad(void) {
#ifdef APP_SAVE_SIZE
    // API info + util
    // Short: OCT_save_read reads a range of this app's save area into dst; returns the bytes read, 0 = nothing trustworthy (dst zeroed), < 0 = an OCT_SAVE_* error.
    // Declaration: int OCT_save_read(void* dst, uint32_t offset, uint32_t size);
    // Comment: the area is resolved before on_init, so loading from on_init works. A fresh area reads as zeros: tell "no save yet" by your own magic/version header, never by the return value alone. On firmware without saves: OCT_SAVE_UNSUPPORTED.
    saveRecord_t rec;
    int32_t got = (int32_t)OCT_save_read(&rec, 0U, (uint32_t)sizeof(rec));
    vars.save.lastResult = got;

    // The rule: a record is overwritten ONLY when it is today's layout or a layout this build knows how to upgrade.
    //  - got < 0: no usable area -> defaults, writes off.
    //  - not ours (got == 0 / short read / other magic, a fresh area reads as zeros) -> defaults, writes on.
    //  - ours, today's SAVE_VERSION and size -> use it, writes on.
    //  - ours, an OLDER version this build migrates -> read through the old layout, upgrade in memory, writes on
    //    (add one `else if (rec.header.version == N)` branch per known old layout here; the template has none yet).
    //  - ours, any OTHER version (newer build, unknown layout, wrong size) -> defaults for this session, writes OFF:
    //    the record is preserved for the build that understands it instead of being silently replaced.
    bool mine = (got == (int32_t)sizeof(rec)) && (rec.header.magic == SAVE_MAGIC);
    if (got < 0) {
        saveDefaults();
        vars.save.valid = false;
    } else if (!mine) {
        saveDefaults();
        vars.save.valid = true;
    } else if (rec.header.version == (uint16_t)SAVE_VERSION && rec.header.size == (uint16_t)sizeof(rec)) {
        vars.save.rec = rec;
        vars.save.valid = true;
    } else {
        saveDefaults();
        vars.save.valid = false; // unknown/newer layout: never write over it
    }
#endif
}

// Util: copy this code if the game keeps a save
void saveDefaults(void) {
#ifdef APP_SAVE_SIZE
    memset(&vars.save.rec, 0, sizeof(vars.save.rec));
    vars.save.rec.header.magic = SAVE_MAGIC;
    vars.save.rec.header.version = (uint16_t)SAVE_VERSION;
    vars.save.rec.header.size = (uint16_t)sizeof(saveRecord_t);
#endif
}

// Util: copy this code if the game keeps a save
int32_t saveStore(void) {
#ifdef APP_SAVE_SIZE
    // API info + util
    // Short: OCT_save_write stores a range of this app's save area; OCT_SAVE_OK (0) = the bytes are on the card when the call returns.
    // Declaration: int OCT_save_write(const void* src, uint32_t offset, uint32_t size);
    // Comment: it BLOCKS for as long as the card needs (a fraction of a frame for a few bytes, a visible hitch for hundreds of KB): store small records at safe moments (new best, level end) and in on_save. A local buffer is fine.
    // Comment: deterministic games write the same bytes on all 8 modules on the same tick. A "Saving" pill shows if it blocked >= 1 frame, "Save failed" on an error (not inside on_save).
    vars.save.rec.header.magic = SAVE_MAGIC;
    vars.save.rec.header.version = (uint16_t)SAVE_VERSION;
    vars.save.rec.header.size = (uint16_t)sizeof(saveRecord_t);
    vars.save.lastResult = (int32_t)OCT_save_write(&vars.save.rec, 0U, (uint32_t)sizeof(saveRecord_t));
#else
    vars.save.lastResult = OCT_SAVE_NO_AREA;
#endif
    return vars.save.lastResult;
}

// Util: copy this code if the game offers "new game"
void saveErase(void) {
    // API info + util
    // Short: OCT_save_erase puts the whole save area back to the install's zeros ("new game"); returns OCT_SAVE_OK or < 0.
    // Declaration: int OCT_save_erase();
    // Comment: refused during a dock reset; invalidates what OCT_scratch() held (the engine streams the rebuild through it).
#ifdef APP_SAVE_SIZE
    vars.save.lastResult = (int32_t)OCT_save_erase();
    saveDefaults();
#else
    vars.save.lastResult = OCT_SAVE_NO_AREA;
#endif
}


// demo

// Demo: do not copy-paste this code
void initDemo0(void) {
    // API info + demo
    // Demo 0: how to add sprites

    for (size_t plane = OCT_PLANE_TOP; plane < OCT_PLANES_MAX; plane++) {
        for (int16_t y = -120; y <= 120; y += 240) {
            for (int16_t x = -120; x <= 120; x+= 240) {
                // OCT_add(0, false, (int32_t)plane, (float)x, (float)y, 0, false, BMP_000, BMP_000, 0);

                if (plane == OCT_PLANE_TOP) {
                    // Short: OCT_add adds a sprite to the scene; returns its index in gObjects, or 0 when the pool is full.
                    // Declaration: int OCT_add(int layer, bool twistable, int plane, float x, float y, int a, bool loop, int bmpfrom, int bmpto, int framelen);
                    // Comment: 0 is never a sprite (slot 0 is the pool's free-list head): check > 0 before using &gObjects[id] (spriteAt).
                    // Comment: twistable=true: a twist carries the sprite with the turning layer (it changes plane/position like the picture under it). twistable=false: twists do not move it, it keeps its scene position while the screens turn under it.
                    // Comment: parameter 'a' is the sprite angle in degrees (int, not float); only right angles are drawn (0, 90, 180, 270). Positive values rotate counter-clockwise (CCW), 0 degrees points right (+X).
                    // Comment: (loop, bmpfrom, bmpto, framelen) start a frame animation; each frame lasts bmp.Rate * framelen + 1 ticks (Rate is 1 for pipeline-packed art: framelen 0 = 20 fps, 1 = 10 fps, 3 = 5 fps).
                    // Critical Comment: with plane 0..5 the engine pushes x/y outward by GAP for you - pass (+-120, +-120) for quad centres. OCT_TM_set/move/walk, tweens and direct Tm writes do NOT: there a quad centre is (+-(120 + GAP), +-(120 + GAP)). Plane OCT_PLANE_WITH_BORDER + p disables the push. A sprite that must FILL the screen goes at (+-QUAD_FILL, +-QUAD_FILL) = +-119.5 instead, or a 2-px background line shows on the inner screen edges.
                    // Comment: draw order = Layer * 8192 - Y (higher layer on top; inside a layer lower on the face is drawn later); keep Layer <= ~120. <FULLSIZE> art always draws above half-res art.
                    OCT_add(1, true, (int32_t)plane, (float)x, (float)y, 0, false, BMP_001, BMP_001, 0);
                }
            }
        }
    }

    OCT_add(1, true, OCT_PLANE_FRONT, 120.f, 120.f, 0, false, BMP_001, BMP_001, 0);
}

