// Demo: do not copy-paste this code
void tapDemo0(size_t plane) {
    // API info + demo
    // Demo 0: how to delete objects + play sounds + use random

    const int32_t sounds[3] = {vars.snd.music, vars.snd.sfxA, vars.snd.sfxB};

    // Short: OCT_random returns a random integer in the range [dmin; dmax).
    // Declaration: int OCT_random(int dmin, int dmax);
    // Comment: dmax is exclusive and must be > dmin (range <= 131 073). It is the cube-wide generator, re-anchored per tick and per command: on_init, on_tick and the input callbacks draw the same values on all 8 modules. Never call it in on_proc_draw; cosmetic per-face randomness uses OCT_random_local (demo 19).
    size_t pick = (size_t)OCT_random(0, 3);
    bool deleted = false;

    for (size_t i = 1; i < SPRITES_CAP; i++) {
        appObject_t* obj = &gObjects[i];
        if ((size_t)obj->Idx != i || (size_t)obj->Tm.Plane != plane) continue;

        // Short: OCT_del deletes a sprite from the scene.
        // Declaration: void OCT_del(octSprite_t* s);
        // Comment: Also deletes its child sprites (label glyphs) and cancels every engine tween (OCT_ANIM_tm) targeting it. The freed index goes to the next OCT_add (LIFO): null every pointer you kept to it. Deleting index 0 or a freed slot only logs on the cube.
        OCT_del(obj);
        deleted = true;
    }

    // one sound per event, not one per deleted sprite: every SND_play takes one of the module's 6 voices
    if (deleted) playSound(sounds[pick], SFX_VOLUME);
}

