    // Rings grouped by axis: 2 TOP, 2 FRONT, 2 LEFT. Each ring is a CW loop through 4 faces.

    vars.demo6.obj = spriteAt((int32_t)OCT_add(0, false, OCT_PLANE_TOP, 120.f, 120.f, 0, false, BMP_001, BMP_001, 0));
