// Demo: do not copy-paste this code
void startTweenDemo10(void) {
    // API info + demo
    // Demo 10: start a tween from the sprite's current transform to the mirrored quad on the same plane.

    appObject_t* obj = vars.demo10.obj;
    if (obj == NULL) return;

    octTm_t from;
    octTm_t to;
    OCT_TM_copy(&from, &obj->Tm);
    OCT_TM_copy(&to, &obj->Tm);
    to.X = -from.X; // mirrored quad, same plane (positions already include the engine's GAP offset)

    ANIM_FUNC func = DEMO10_FUNCS[vars.demo10.funcIdx];
    float arc = (func == FUNC_LINEAR) ? 0.f : 60.f;

    // Short: OCT_ANIM_tm starts an engine-driven tween that writes X, Y and Plane into *target every tick; returns the tween index 1..98, 0 = no free slot (ANIMS_CAP 100).
    // Declaration: int OCT_ANIM_tm(float arc, int delay_ticks, int duration_ticks, void* context, int func, octTm_t* from, octTm_t* to, bool reffrom, bool refto, octTm_t* target);
    // Comment: arc is an extra Y offset at mid-flight (0 = straight line, > 0 = ballistic hop); 'to' may be on an adjacent plane, the tween crosses the edge (opposite planes are not supported). A is never animated. context is unused. duration_ticks must be > 0.
    // Comment: func is an easing from enum ANIM_FUNC (never FUNC_NONE): FUNC_LINEAR, FUNC_ACC, FUNC_DEC, FUNC_BOUNCEOUT, FUNC_FALL move to 'to'; FUNC_QUAD, FUNC_JELLY, FUNC_SPAWN are effects that RETURN to 'from'.
    // Comment: reffrom/refto = true stores the POINTER and re-reads it every tick (a moving target that must outlive the tween); false copies the transform now.
    // Comment: tweens update AFTER on_tick (logic sees the new position next tick) and freeze while the game is held; OCT_del of the target sprite deletes its tweens.
    vars.demo10.anim = (int32_t)OCT_ANIM_tm(arc, 0, OCT_1SEC_TICKS, NULL, (int32_t)func, &from, &to, false, false, &obj->Tm);
    vars.demo10.halfLogged = false;

    OCT_text(-1, "Demo10 tween func=%d arc=%d anim=%d\n", (int32_t)func, (int32_t)arc, vars.demo10.anim);
}

// Demo: do not copy-paste this code
void startChaserDemo10(void) {
    // API info + demo
    // Demo 10: tween the chaser towards the main sprite's LIVE transform (refto = true).

    appObject_t* chaser = vars.demo10.chaser;
    if (chaser == NULL || vars.demo10.obj == NULL) return;

    octTm_t from;
    OCT_TM_copy(&from, &chaser->Tm);

    // Short: OCT_ANIM_tm_tw is OCT_ANIM_tm for twistable content: physical and virtual twists also twist the tween's stored (non-ref) endpoints.
    // Declaration: int OCT_ANIM_tm_tw(float arc, int delay_ticks, int duration_ticks, void* context, int func, octTm_t* from, octTm_t* to, bool reffrom, bool refto, octTm_t* target);
    // Comment: Here 'to' is a pointer to the main sprite's Tm (refto = true), so the chaser re-aims every tick while its target moves.
    vars.demo10.chaserAnim = (int32_t)OCT_ANIM_tm(0.f, 0, 2 * OCT_1SEC_TICKS, NULL, FUNC_DEC, &from, &vars.demo10.obj->Tm, false, true, &chaser->Tm);
}

// Demo: do not copy-paste this code
void processDemo10(void) {
    // API info + demo
    // Demo 10: poll tween events and chain the next tween.

    if (vars.demo10.anim != 0) {
        // Short: OCT_ANIM_on_half returns 1 on EVERY tick once a tween is past its half-way point (a level, not a one-tick pulse).
        // Declaration: int OCT_ANIM_on_half(int aidx);
        if (!vars.demo10.halfLogged && OCT_ANIM_on_half(vars.demo10.anim) != 0) {
            vars.demo10.halfLogged = true;

            // Short: OCT_ANIM_get_progress returns the tween's tick counter: negative while delayed, then 0..duration_ticks; 0 for an invalid id.
            // Declaration: int OCT_ANIM_get_progress(int aidx);
            OCT_text(-1, "Demo10 half-way at progress=%d\n", (int32_t)OCT_ANIM_get_progress(vars.demo10.anim));
        }

        // Short: OCT_ANIM_on_end returns 1 during the single on_tick after a tween reached its end; the tween is deleted on the next update and its index may be reused - zero your stored id.
        // Declaration: int OCT_ANIM_on_end(int aidx);
        if (OCT_ANIM_on_end(vars.demo10.anim) != 0) {
            vars.demo10.anim = 0;
            vars.demo10.funcIdx = (vars.demo10.funcIdx + 1) % DEMO10_FUNC_COUNT;
            startTweenDemo10();
        }
    }

    if (vars.demo10.chaserAnim != 0 && OCT_ANIM_on_end(vars.demo10.chaserAnim) != 0) {
        vars.demo10.chaserAnim = 0;
        startChaserDemo10();
    }

    // Short: OCT_ANIM_del cancels a running tween by index (a stale or zero index is ignored).
    // Declaration: void OCT_ANIM_del(int aidx);
    if (vars.tick == (uint32_t)(30 * OCT_1SEC_TICKS) && vars.demo10.chaserAnim != 0) {
        OCT_ANIM_del(vars.demo10.chaserAnim);
        vars.demo10.chaserAnim = 0;
        OCT_text(-1, "Demo10 chaser stopped\n");
    }
}


// Utils (copy them): place content upright for the player on any face.
// An "up" angle a (0/90/180/270) is counter-clockwise from the plane's +Y, as OCT_TM_face_up returns it (engine
// oct_tm.h: U = cos(a)*B3D - sin(a)*T3D), so in plane coordinates up = (-sin a, cos a) and the player's right =
// (cos a, sin a). uprightOffset() turns an offset given as the player sees the face (ux to the right, uy up) into
// plane x,y; the same a is the sprite angle that draws it upright (assign it to Tm.A or pass it to OCT_add).
static inline void uprightOffset(int32_t a, float ux, float uy, float* x, float* y) {
    switch (a) {
        case 0:   *x = ux;  *y = uy;  break;
        case 90:  *x = -uy; *y = ux;  break;
        case 180: *x = -ux; *y = -uy; break;
        default:  *x = uy;  *y = -ux; break;     // 270
    }
}

// UP_TOWARD[p][s]: the up angle of face s that points at the adjacent face p (-1: s is p or its opposite). Pure cube
// geometry from the engine's axis tables, checked against OCT_TM_face_up on all six faces up in the simulator.
static const int16_t UP_TOWARD[6][6] = {
    { -1,   0,   0,   0,   0,  -1},   // toward TOP
    {180,  -1,  90,  -1, 270,   0},   // toward FRONT
    {270, 270,  -1,  90,  -1, 270},   // toward RIGHT
    {  0,  -1, 270,  -1,  90, 180},   // toward BACK
    { 90,  90,  -1, 270,  -1,  90},   // toward LEFT
    { -1, 180, 180, 180, 180,  -1},   // toward BOTTOM
};

// The four faces around the playfield (HUD, panoramas): upright = "up" points at the playfield. Geometry, so it never
// lags: use it instead of OCT_TM_face_up(side) for those faces. Returns the angle, -1 when side is not adjacent.
static inline int32_t uprightAround(int32_t playfield, int32_t side, float ux, float uy, float* x, float* y) {
    int32_t a = (int32_t)UP_TOWARD[playfield][side];
    if (a >= 0) uprightOffset(a, ux, uy, x, y);
    return a;
}

// The playfield's own rotation: the engine's latched up, as system notifications use it.
static inline int32_t uprightToPlane(int32_t plane, float ux, float uy, float* x, float* y) {
    int32_t a = (int32_t)OCT_TM_normalize_angle(((OCT_TM_face_up(plane) + 45) / 90) * 90);
    uprightOffset(a, ux, uy, x, y);
    return a;
}

