// Demo: do not copy-paste this code
void processDemo14(void) {
    // API info + demo
    // Demo 14: refresh the clock label once a second, log the host state, undim after 2 seconds.

    if (vars.tick == (uint32_t)(2 * OCT_1SEC_TICKS)) restoreBrightnessDemo14();
    if (vars.tick % (uint32_t)OCT_1SEC_TICKS != 0U) return;

    // Short: OCT_calendar_time returns the cube's LOCAL wall-clock time as a UNIX epoch in seconds (zone offset already applied).
    // Declaration: uint32_t OCT_calendar_time(void);
    // Comment: Returns 1 while the RTC is unset; the simulator reports UTC. Each module reads its own RTC: display only.
    uint32_t now = OCT_calendar_time();
    uint32_t secondsInDay = now % 86400U;
    uint32_t hour = secondsInDay / 3600U;
    uint32_t minute = (secondsInDay / 60U) % 60U;

    char buf[8];
    snprintf(buf, sizeof(buf), "%02u:%02u", hour, minute);
    if (vars.demo14.clock != NULL) OCT_label_set(vars.demo14.clock, buf);

    // Short: OCT_BAT_level returns the cube battery percent 0..100 (the most discharged cublet, settled); -1 = not measured yet.
    // Declaration: int8_t OCT_BAT_level(void);
    // Comment: OCT_BAT_level_local is this cublet's own reading - use OCT_BAT_level for anything the user sees.
    int8_t battery = OCT_BAT_level();
    int8_t batteryLocal = OCT_BAT_level_local();

    // Short: OCT_first_run is true for the whole session in which the onboarding pack was autostarted; OCT_fw_up_to_date is the phone's verdict on the firmware.
    // Declaration: OCT_first_run() / OCT_fw_up_to_date() - macros returning bool (false on firmware without them).
    bool firstRun = OCT_first_run();

    OCT_text(-1, "Demo14 %s bat=%d local=%d first=%d\n", buf, (int32_t)battery, (int32_t)batteryLocal, (int32_t)firstRun);

#ifdef OCT_APP_MODULE
    // These macros have no prototype in the Windows simulator (it compiles the app header before the engine): module build only.
    // Short: OCT_screen_quad returns the scene quad (0..23) shown on this module's display 0..2, or -1 if unbound (per module).
    // Declaration: OCT_screen_quad(display) - macro.
    OCT_text(-1, "Demo14 displays -> quads %d,%d,%d\n", (int32_t)OCT_screen_quad(0), (int32_t)OCT_screen_quad(1), (int32_t)OCT_screen_quad(2));

    // Short: OCT_host_info copies a phone-facing payload (HOST_KIND_BATTERY, HOST_KIND_SETTINGS, HOST_KIND_DEVICE_INFO ...) into out; returns its full length, 0 when not served or on firmware < fw-0.100.5.
    // Declaration: OCT_host_info(kind, out, size) - macro.
    octHostBattery_t bat;
    memset(&bat, 0, sizeof(bat));
    if ((int32_t)OCT_host_info((uint32_t)HOST_KIND_BATTERY, &bat, (uint32_t)sizeof(bat)) > 0)
        OCT_text(-1, "Demo14 host battery=%d charging=%d module0=%d link=%d\n", (int32_t)bat.CubePercent, (int32_t)bat.Charging, (int32_t)bat.ModulePercent[0], (int32_t)OCT_link_status());
#endif
}

