// Demo: do not copy-paste this code
void initDemo16(void) {
    // API info + demo
    // Demo 16: viewports - each of the 24 displays is a camera looking at a quad of the scene; re-aim them for mirrors and split views.

    for (int16_t y = -120; y <= 120; y += 240) {
        for (int16_t x = -120; x <= 120; x += 240) {
            OCT_add(1, false, OCT_PLANE_TOP, (float)x, (float)y, 0, false, BMP_001, BMP_001, 0);
        }
    }

    // Short: OCT_modify_viewport re-aims display vid (0..23 = plane * 4 + sector) at a plane of the scene with the given camera transform.
    // Declaration: void OCT_modify_viewport(int vid, int plane, int angle, float x, float y, int xflip, int yflip, int mode);
    // Comment: The camera transform is INVERTED: the default layout for sector s of plane p is (plane = p, angle = -90 * s, x = y = -(GAP + 0.01), xflip = yflip = 1, mode = 0). Start from these values and change one thing.
    // Comment: mode 0 = normal, 2 = disabled (draws nothing), -1 keeps the current mode. The change persists until OCT_viewports_layout(SCHEME_CUBE, GAP, GAP) restores everything (switchDemo does).
    for (int32_t sector = 0; sector < OCT_QUADS_AT_PLANE; sector++) {
        int32_t vid = OCT_PLANE_BOTTOM * OCT_QUADS_AT_PLANE + sector;
        OCT_modify_viewport(vid, OCT_PLANE_TOP, -90 * sector, -(float)GAP, -(float)GAP, 1, 1, 0);
    }
}


// Demo: do not copy-paste this code
void initDemo17(void) {
    // API info + demo
    // Demo 17: the sound mixer - a looping music bed, effects on top of it, a positional sound, a hard cut.
    // Every sound goes through playSound()/playSoundAt(): TPL_MUTE compiles all of it out.
    vars.demo17.musicNextTick = vars.tick; // start the bed now
    vars.demo17.musicOn = true;
    OCT_text(-1, "Demo17: tap = a sound on that screen, double tap = next demo\n");
}

// Demo: do not copy-paste this code
void processDemo17(void) {
    // API info + demo
    if (vars.demo17.musicOn) updateMusic();

    // an effect every 2 seconds on top of the bed: with the mixer on (the default) the voices add up
    if (vars.tick % (uint32_t)(2 * OCT_1SEC_TICKS) == (uint32_t)OCT_1SEC_TICKS) playSound(vars.snd.sfxB, 60);

    // at 8 s: a hard cut
    if (vars.tick == (uint32_t)(8 * OCT_1SEC_TICKS)) {
        // Short: SND_set_mixer(false) makes the NEXT SND_play on this module fade out (52 ms) everything it plays - music, effects, system chimes - and take over; SND_set_mixer(true) mixes again (the default; reset at app teardown).
        // Declaration: void SND_set_mixer(bool on);
        // Comment: the switch itself touches nothing already playing. Off -> play -> on = "stop everything and play this", the only way to cut sounds (there is no stop API). Leave it off for one-channel games (an announcer, an engine loop re-triggered per event).
        SND_set_mixer(false);
        playSound(vars.snd.sfxA, SFX_VOLUME);
        SND_set_mixer(true);
        vars.demo17.musicOn = false; // the bed was cut: stop retriggering it
    }

    // at 12 s: the bed comes back
    if (vars.tick == (uint32_t)(12 * OCT_1SEC_TICKS)) {
        vars.demo17.musicOn = true;
        vars.demo17.musicNextTick = vars.tick;
    }
}

