// Demo: do not copy-paste this code
void initDemo19(void) {
    // API info + demo
    // Demo 19: colour without extra art (OCT_tint_mode blend modes), a tinted static caption, a Line sprite, and
    // particles whose existence is deterministic (OCT_random) while their jitter is cosmetic (OCT_random_local).

    // Short: OCT_tint_mode sets a sprite's Data0 (RGB565 colour) and Blend (how it is applied) in one call; returns the number of sprites recoloured (1 + a label's glyphs).
    // Declaration: int OCT_tint_mode(octSprite_t* s, int color565, int mode);
    // Comment: modes, per channel and saturating: OCT_BLEND_MUL (exact recolour; identity white = OCT_TINT_NONE 0xFFFF), OCT_BLEND_ADD (flash/glow), OCT_BLEND_SUB (darken), OCT_BLEND_SCREEN (lighten) - identity 0x0000 for these three - and OCT_BLEND_HUE (color565 is an ANGLE in degrees, snapped to 60 steps).
    // Comment: back to the baked art: OCT_tint_mode(s, OCT_TINT_NONE, OCT_BLEND_MUL). Data0 IS the tint of every sprite (born 0xFFFF): never store game data in it. Procedural text/circle and Line paint Data0 straight (only MUL makes sense there); PROCEDURAL_CUSTOM is not coloured by the engine.
    // Comment: cost per frame: palette art per palette entry, RAW565/ARGB art per pixel; up to 16 tinted palette variants are cached per frame. On firmware older than fw-0.100.1 only MUL works (it falls back to OCT_tint, fw-0.98.19+).
    const int32_t modes[OCT_QUADS_AT_PLANE] = {OCT_BLEND_MUL, OCT_BLEND_ADD, OCT_BLEND_SUB, OCT_BLEND_SCREEN};
    const int32_t colors[OCT_QUADS_AT_PLANE] = {(int32_t)COLOR_RED, (int32_t)COLOR_GRAY, (int32_t)COLOR_GRAY, (int32_t)COLOR_BLUE};
    for (int32_t q = 0; q < OCT_QUADS_AT_PLANE; q++) {
        appObject_t* s = spriteAt((int32_t)OCT_add(1, false, OCT_PLANE_TOP, 120.f * (float)XSIGN[q], 120.f * (float)YSIGN[q], 0, false, BMP_001, BMP_001, 0));
        vars.demo19.modes[q] = s;
        if (s != NULL) OCT_tint_mode(s, colors[q], modes[q]);
    }

    vars.demo19.hue = spriteAt((int32_t)OCT_add(1, false, OCT_PLANE_FRONT, 120.f, 120.f, 0, false, BMP_002, BMP_002, 0));

    // Short: OCT_label_static lays a label's text out once without taking one of the 64 engine text slots; returns the length, 0 on failure.
    // Declaration: int OCT_label_static(octSprite_t* label, const char* text);
    // Comment: every call is a full glyph rebuild (no memo): use it for captions and HUD text that rarely changes, OCT_label_set (memoized, uses a slot) for text that changes often. Limited only by the sprite pool (one slot per glyph).
    // Warn: no NULL guard in the module macro: needs cube firmware >= fw-0.98.19, older firmware crashes.
    vars.demo19.caption = spriteAt((int32_t)OCT_add_label(2, false, OCT_PLANE_FRONT, -120.f, 120.f, 0, FONT_1, ALIGN_CENTER));
    if (vars.demo19.caption != NULL) {
        OCT_label_static(vars.demo19.caption, "TINT");
        OCT_tint_mode(vars.demo19.caption, (int32_t)COLOR_YELLOW, OCT_BLEND_MUL); // also tints every glyph child
    }

    // Short: a Line sprite draws a 1-pixel line from its Tm to Tm + (Zw, Zh) (rotated by Tm.A) in colour Data0, over everything else.
    // Comment: OCT_add with bitmaps 0, then Line = 1. It uses its own Tm only (no parent composition) and ignores Mask.
    appObject_t* line = spriteAt((int32_t)OCT_add(3, false, OCT_PLANE_FRONT, -200.f, -60.f, 0, false, 0, 0, 0));
    if (line != NULL) {
        line->Line = 1;
        line->Zw = (int16_t)160;
        line->Zh = (int16_t)0;
        line->Data0 = COLOR_WHITE;
    }
}

// Demo: do not copy-paste this code
void processDemo19(void) {
    // API info + demo

    // hue rotation: one full turn every 3 seconds (Data0 changes -> the face redraws)
    if (vars.demo19.hue != NULL) OCT_tint_mode(vars.demo19.hue, (int32_t)((vars.tick * 6U) % 360U), OCT_BLEND_HUE);

    // hit flash: ADD white for 2 ticks once a second, otherwise the plain ADD grey (same value = no redraw)
    appObject_t* flash = vars.demo19.modes[1];
    if (flash != NULL) {
        uint32_t phase = vars.tick % (uint32_t)OCT_1SEC_TICKS;
        OCT_tint_mode(flash, (phase < 2U) ? 0xFFFF : (int32_t)COLOR_GRAY, OCT_BLEND_ADD);
    }

    // particles: WHETHER a spark appears and on WHICH screen is decided by OCT_random (identical on all 8 modules, so the
    // sprite pool stays identical); its jitter, size and colour are cosmetic, so OCT_random_local may differ per module.
    if (vars.tick % 4U == 0U) {
        int32_t q = (int32_t)OCT_random(0, OCT_QUADS_AT_PLANE);
        // Short: OCT_random_local is the per-module generator for effects that may differ between faces; same [dmin; dmax) contract as OCT_random.
        // Declaration: int OCT_random_local(int dmin, int dmax);
        // Comment: never let it decide game state or whether a sprite exists. Older firmware: a private stream, identical on every module (never OCT_random).
        float x = (120.f + (float)OCT_random_local(-60, 61)) * (float)XSIGN[q];
        float y = (120.f + (float)OCT_random_local(-60, 61)) * (float)YSIGN[q];
        appObject_t* spark = spriteAt((int32_t)OCT_add(4, false, OCT_PLANE_RIGHT, x, y, 0, false, 0, 0, 0));
        if (spark != NULL) {
            spark->Procedural = PROCEDURAL_CIRCLE;
            spark->Param3 = (int8_t)OCT_random_local(6, 20);
            spark->Data0 = COLORS[OCT_random_local(0, COLORS_COUNT)];
            // Short: Autokill + AgeMark: the engine deletes the sprite by itself once AgeTicks (+1 every non-held tick) reaches AgeMark.
            // Comment: fire-and-forget only: never keep a pointer to an Autokill sprite, its slot is reused after it vanishes.
            spark->AgeMark = (uint16_t)OCT_1SEC_TICKS;
            spark->Autokill = 1;
        }
    }
}


