    octTapSource_t src;
    memset(&src, 0, sizeof(src));
    OCT_tap_source(&src, (uint32_t)sizeof(src));
    OCT_text(-1, "Demo20 tap plane=%d quad=%d module=%d screen=%d amp=%d agree=%d\n",
        tapid, quad, (int32_t)src.Module, (int32_t)src.Screen, (int32_t)src.Amplitude, (int32_t)src.Agreeing);
